using AlshrouqSchool.Domain.Contracts; using AlshrouqSchool.Domain.Entities.MediaAndContentModule; using AlshrouqSchool.Shared.DTOs.Gallery.Common; using AlshrouqSchool.Shared.DTOs.Gallery.Media; using AutoMapper; using MediatR;
namespace AlshrouqSchool.Application.Features.Gallery.Queries.Media;
public sealed record GetMediaByIdQuery(int Id):IRequest<MediaDto?>; public sealed record GetGalleryMediaQuery(MediaQueryParameters Parameters):IRequest<PagedResult<MediaDto>>;
public sealed class GetMediaByIdQueryHandler(IUnitOfWork u,IMapper m):IRequestHandler<GetMediaByIdQuery,MediaDto?>{public async Task<MediaDto?> Handle(GetMediaByIdQuery r,CancellationToken ct){var e=await u.GetRepository<Media,int>().GetByIdAsync(r.Id);return e is null||e.IsDeleted?null:m.Map<MediaDto>(e);}}
public sealed class GetGalleryMediaQueryHandler(IUnitOfWork u,IMapper m):IRequestHandler<GetGalleryMediaQuery,PagedResult<MediaDto>>{public async Task<PagedResult<MediaDto>> Handle(GetGalleryMediaQuery r,CancellationToken ct){var p=r.Parameters;var q=(await u.GetRepository<Media,int>().GetAllAsync()).Where(x=>!x.IsDeleted&&x.Category==AlshrouqSchool.Core.Entities.MediaCategory.Gallery);if(p.Type.HasValue)q=q.Where(x=>x.Type==p.Type);if(p.Category.HasValue)q=q.Where(x=>x.Category==p.Category);if(!string.IsNullOrWhiteSpace(p.Search))q=q.Where(x=>x.FileName.Contains(p.Search,StringComparison.OrdinalIgnoreCase));var total=q.Count();var page=Math.Max(1,p.PageNumber);var size=Math.Clamp(p.PageSize,1,100);return new(m.Map<List<MediaDto>>(q.OrderByDescending(x=>x.CreatedAtUtc).Skip((page-1)*size).Take(size)),page,size,total);}}